<!doctype html><html lang="en"><head><meta charset="utf-8"><title>CityCare receipt {{ $payment->reference_number }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#0f172a;font-size:12px;margin:36px}.header{border-bottom:3px solid #0f766e;padding-bottom:16px;margin-bottom:24px}.brand{font-size:22px;font-weight:bold;color:#0f766e}.muted{color:#64748b}.label{color:#64748b;width:42%}table{width:100%;border-collapse:collapse;margin-top:22px}td{padding:10px;border-bottom:1px solid #e2e8f0}.total{font-size:16px;font-weight:bold}.footer{margin-top:36px;border-top:1px solid #cbd5e1;padding-top:12px;color:#64748b}</style></head><body><header class="header"><div class="brand">CityCare Medical Centre</div><div class="muted">Patient payment receipt · Kampala, Uganda</div></header><h2>Receipt {{ $payment->reference_number }}</h2><p class="muted">Generated {{ now()->format('j F Y, g:i A') }} by {{ auth()->user()->name }}</p><table><tr><td class="label">Patient</td><td>{{ $payment->patient->first_name }} {{ $payment->patient->last_name }} ({{ $payment->patient->patient_number }})</td></tr><tr><td class="label">Appointment</td><td>{{ $payment->appointment->appointment_date->format('j F Y') }} · {{ $payment->appointment->doctor->user->name }}</td></tr><tr><td class="label">Department</td><td>{{ $payment->appointment->department->name }}</td></tr><tr><td class="label">Payment method</td><td>{{ ucfirst(str_replace('_',' ',$payment->payment_method)) }}</td></tr><tr><td class="label">Payment status</td><td>{{ ucfirst($payment->status) }}</td></tr><tr><td class="label">Amount charged</td><td>UGX {{ number_format((float)$payment->amount) }}</td></tr><tr><td class="label">Amount received</td><td class="total">UGX {{ number_format((float)$payment->amount_paid) }}</td></tr><tr><td class="label">Balance due</td><td>UGX {{ number_format($payment->balance) }}</td></tr></table><footer class="footer">Thank you for choosing CityCare Medical Centre. Keep this receipt for your records.</footer></body></html>
